import React, { useState, useEffect, useCallback } from 'react';
import axios from 'axios';
import io from 'socket.io-client';
import { useNavigate } from 'react-router-dom';
import './AdminPanel.css';
import { BACKEND_URL } from '../../config'; // Ensure this matches your config path

const AdminPanel = () => {
    const token = localStorage.getItem('token');
    const navigate = useNavigate();

    // States
    const [players, setPlayers] = useState([]);
    const [filteredPlayers, setFilteredPlayers] = useState([]);
    const [categoryFilter, setCategoryFilter] = useState('All');

    const [events, setEvents] = useState([]);
    const [newEventName, setNewEventName] = useState('');
    const [newEventBudget, setNewEventBudget] = useState('');
    const [newEventStart, setNewEventStart] = useState('');

    const [socket, setSocket] = useState(null);
    const [loading, setLoading] = useState(true);
    const [matches, setMatches] = useState([]);
    const [selectedEventId, setSelectedEventId] = useState(null);
    const [matchesLoading, setMatchesLoading] = useState(false);

    /* ---------------- 1. SOCKET SETUP & REDIRECTION (Requirement 5) ---------------- */
    useEffect(() => {
        if (!token) return;

        const s = io(BACKEND_URL, { auth: { token } });
        setSocket(s);

        // Listen for the start signal to redirect the Admin to the live screen
        s.on("redirect_live", () => {
            navigate('/live-auction');
        });

        return () => s.disconnect();
    }, [token, navigate]);

    /* ---------------- 2. DATA FETCHING ---------------- */
    const fetchPlayers = useCallback(async () => {
        try {
            const res = await axios.get(`${BACKEND_URL}/api/admin/players`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setPlayers(res.data);
            setFilteredPlayers(res.data);
            setLoading(false);
        } catch (err) {
            console.error("Error fetching players", err);
        }
    }, [token]);

    const fetchEvents = useCallback(async () => {
        try {
            const res = await axios.get(`${BACKEND_URL}/api/events`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setEvents(res.data);
            const active = res.data.find(e => e.isActive);
            if (active) fetchMatches(active._id);
        } catch (err) {
            console.error("Error fetching events", err);
        }
    }, [token]);

    useEffect(() => {
        fetchPlayers();
        fetchEvents();
    }, [fetchPlayers, fetchEvents]);

    /* ---------------- 3. CATEGORY FILTERING (Requirement 2) ---------------- */
    useEffect(() => {
        if (categoryFilter === 'All') {
            setFilteredPlayers(players);
        } else {
            setFilteredPlayers(players.filter(p => p.role === categoryFilter));
        }
    }, [categoryFilter, players]);

    /* ---------------- 4. MATCH SCHEDULE & CONFLICT LOGIC (Requirement 3) ---------------- */
    const fetchMatches = async (eventId) => {
        try {
            setMatchesLoading(true);
            setSelectedEventId(eventId);
            const res = await axios.get(`${BACKEND_URL}/api/events/${eventId}/matches`, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setMatches(res.data);
        } catch (err) {
            console.error("Error fetching matches", err);
        } finally {
            setMatchesLoading(false);
        }
    };

    const createEvent = async () => {
        if (!newEventName) return;

        // Check for Conflict: Prevent two times from being the same
        const conflict = events.some(e => e.startTime === newEventStart);
        if (conflict) {
            alert("Conflict: This time slot is already occupied. Please pick another time.");
            return;
        }

        try {
            const payload = { name: newEventName };
            if (newEventBudget) payload.teamBudget = Number(newEventBudget);
            if (newEventStart) payload.startTime = newEventStart;

            const res = await axios.post(`${BACKEND_URL}/api/events`, payload, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setEvents([res.data, ...events]);
            setNewEventName('');
            setNewEventBudget('');
            setNewEventStart('');
            alert("Event Scheduled Successfully!");
        } catch (err) {
            console.error("Error creating event", err);
        }
    };

    /* ---------------- 5. AUCTION ACTIONS (Requirement 5) ---------------- */
    const startAuction = (playerId) => {
        if (window.confirm("Start Live Auction for this player? All users will be redirected.")) {
            socket.emit("admin_start_auction", playerId);
            // The 'redirect_live' socket listener above will handle navigation
        }
    };

    const approvePlayer = async (playerId) => {
        try {
            const res = await axios.post(`${BACKEND_URL}/api/admin/players/${playerId}/approve`, {}, {
                headers: { Authorization: `Bearer ${token}` }
            });
            setPlayers(players.map(p => p._id === playerId ? res.data : p));
        } catch (err) {
            console.error("Error approving player", err);
        }
    };

    if (loading) return <div className="loading">Loading Auction Platform...</div>;

    return (
        <div className="admin-container">
            {/* Requirement 4: Non-clickable Logo */}
            <header className="admin-navbar">
                <div className="logo-text">AUCTION-PRO</div>
                <nav className="nav-links">
                    <button onClick={() => navigate('/dashboard')}>Home</button>
                    <button onClick={() => navigate('/live-auction')}>Live Auction</button>
                    <button className="active">Admin Panel</button>
                </nav>
            </header>

            <section className="main-section">
                <h2>Admin Control Panel</h2>

                {/* Requirement 3: Match Slot Creation */}
                <div className="event-section card-shadow">
                    <h3>Schedule New Match Event</h3>
                    <div className="event-form">
                        <input type="text" placeholder="Event name (e.g. IPL 2026)" value={newEventName} onChange={e => setNewEventName(e.target.value)} />
                        <input type="number" placeholder="Team budget" value={newEventBudget} onChange={e => setNewEventBudget(e.target.value)} />
                        <input type="datetime-local" value={newEventStart} onChange={e => setNewEventStart(e.target.value)} />
                        <button className="primary-btn" onClick={createEvent}>Confirm Slot</button>
                    </div>
                </div>

                {/* Requirement 2: Filter Tabs */}
                <div className="filter-section">
                    <h3>Player Directory</h3>
                    <div className="filter-tabs">
                        {['All', 'Batsman', 'Bowler', 'All-rounder', 'Wicket-keeper'].map(role => (
                            <button 
                                key={role} 
                                className={categoryFilter === role ? 'active-tab' : ''} 
                                onClick={() => setFilter(role)}
                            >
                                {role}
                            </button>
                        ))}
                    </div>

                    <table className="player-list-table">
                        <thead>
                            <tr>
                                <th>Name</th>
                                <th>Category</th>
                                <th>Base Price</th>
                                <th>Status</th>
                                <th>Actions</th>
                            </tr>
                        </thead>
                        <tbody>
                            {filteredPlayers.map(player => (
                                <tr key={player._id}>
                                    <td><button className="link-btn" onClick={() => navigate(`/profile/${player._id}`)}>{player.name}</button></td>
                                    <td>{player.role}</td>
                                    <td>₹{player.basePrice.toLocaleString()}</td>
                                    <td><span className={`badge ${player.status.toLowerCase()}`}>{player.status}</span></td>
                                    <td className="action-cell">
                                        {player.status === 'Pending' && (
                                            <button className="approve-btn" onClick={() => approvePlayer(player._id)}>Approve</button>
                                        )}
                                        {player.status === 'Approved' && (
                                            <button className="start-btn" onClick={() => startAuction(player._id)}>Start Auction</button>
                                        )}
                                    </td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </section>
        </div>
    );
};

export default AdminPanel;
